    public static EdgeAgentDiagnostic Describe(string? diagnosticCode)
    {
        if (string.IsNullOrWhiteSpace(diagnosticCode))
        {
            return new EdgeAgentDiagnostic("Діагностики немає.", "");
        }

        return Diagnostics.TryGetValue(diagnosticCode, out EdgeAgentDiagnostic? diagnostic)
            ? diagnostic
            : new EdgeAgentDiagnostic("Виявлено невідому проблему вузла.", "Зверніться до адміністратора та вкажіть код діагностики.");
    }
